{% set siteUrl = config.url | uriencode %}

  {% for post in posts %}
  {% if (post.permalink | uriencode) != siteUrl and (post.permalink | uriencode) != siteUrl + '/' %}

    {{ post.permalink | uriencode }}
    {% if post.updated %}
    {{ post.updated | formatDate }}
    {% elif post.date %}
    {{ post.date | formatDate }}
    {% endif %}
    monthly
    0.6

  {% endif %}
  {% endfor %}


    {{ config.url | uriencode }}
    {{ sNow | formatDate }}
    daily
    1.0


  {% for tag in tags %}

    {{ tag.permalink | uriencode }}
    {{ sNow | formatDate }}
    weekly
    0.2

  {% endfor %}

  {% for cat in categories %}

    {{ cat.permalink | uriencode }}
    {{ sNow | formatDate }}
    weekly
    0.2

  {% endfor %}
